/**
 * SAUGIKLIS (S477): `_own_stock_qty` rašymas NEGALI paliesti `_stock`.
 *
 * PRIEŽASTIS: S468 testo metu Josera `_stock` iš 653 tapo 2 — lygiai tiek, kiek
 * buvo įrašyta į AV. WooCommerce kabliukai gali sureaguoti į meta pakeitimą ir
 * perrašyti `_stock`. Tikroji reikšmė ateina iš VF sync (`_vf_qty`).
 *
 * Prieš rašydami įsimenam `_stock`; po rašymo — jei pasikeitė, grąžinam.
 */
protected static function apsaugotas_rasymas( $product_id, $reiksme ) {
	$product_id = (int) $product_id;
	$stock_pries = get_post_meta( $product_id, '_stock', true );

	if ( null === $reiksme ) { delete_post_meta( $product_id, self::META ); }
	else { update_post_meta( $product_id, self::META, (int) $reiksme ); }

	$stock_po = get_post_meta( $product_id, '_stock', true );
	if ( (string) $stock_pries !== (string) $stock_po ) {
		update_post_meta( $product_id, '_stock', $stock_pries );
		if ( function_exists( 'wc_update_product_stock_status' ) ) {
			wc_delete_product_transients( $product_id );
		}
		error_log( "[Petshop_AV_Stock] SAUGIKLIS: _stock $product_id buvo pakeistas "
		         . "$stock_pries → $stock_po, grąžinta" );
	}
}

